bool are_anagrams(const std::string &a, const std::string &b) {
    if (a.size() != b.size()) return false;
    int seen[26] = {0};
    for (char c : a) seen[c - 'a']++;
    for (char c : b) seen[c - 'a']--;
    for (int i = 0; i < 26; i++)
        if (seen[i] != 0) return false;
    return true;
}

int main() {
    std::string a, b;
    std::cin >> a >> b;
    std::cout << are_anagrams(a, b) << std::endl;
    return 0;
}

