#include <iostream>

struct Node {
    int data;
    Node* next;
};

Node* append_back(Node* head, int value) {
    Node* node = new Node();
    node->data = value;
    node->next = NULL;
    if (!head) return node;
    Node* cur = head;
    while (cur->next) cur = cur->next;
    cur->next = node;
    return head;
}

void print_list(Node* head) {
    Node* cur = head;
    while (cur) {
        std::cout << cur->data;
        if (cur->next) std::cout << ' ';
        cur = cur->next;
    }
    std::cout << std::endl;
}


int main() {
    int n;
    std::cin >> n;
    Node* head = NULL;
    Node* tail = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        std::cin >> x;
        Node* nd = new Node();
        nd->data = x;
        nd->next = NULL;
        if (!head) head = nd;
        else tail->next = nd;
        tail = nd;
    }
    int value;
    std::cin >> value;
    print_list(append_back(head, value));
    return 0;
}

