struct DNode {
    int data;
    DNode* prev;
    DNode* next;
};

DNode* dll_push_back(DNode* head, int value) {
    DNode* node = new DNode();
    node->data = value;
    node->prev = NULL;
    node->next = NULL;
    if (!head) return node;
    DNode* tail = head;
    while (tail->next) tail = tail->next;
    tail->next = node;
    node->prev = tail;
    return head;
}

int main() {
    int n;
    std::cin >> n;
    DNode* head = NULL;
    DNode* tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        DNode* node = new DNode();
        node->data = v;
        node->prev = tail;
        node->next = NULL;
        if (tail) tail->next = node;
        else head = node;
        tail = node;
    }
    int value;
    std::cin >> value;
    DNode* res = dll_push_back(head, value);
    bool first = true;
    for (DNode* cur = res; cur != NULL; cur = cur->next) {
        if (!first) std::cout << ' ';
        std::cout << cur->data;
        first = false;
    }
    std::cout << "\n";
    return 0;
}

