struct DNode {
    int data;
    DNode* prev;
    DNode* next;
};

std::vector<int> dll_backward(DNode* head) {
    std::vector<int> out;
    DNode* tail = head;
    while (tail && tail->next) tail = tail->next;
    for (DNode* cur = tail; cur != NULL; cur = cur->prev) out.push_back(cur->data);
    return out;
}

int main() {
    int n;
    std::cin >> n;
    DNode* head = NULL;
    DNode* tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        DNode* node = new DNode();
        node->data = v;
        node->prev = tail;
        node->next = NULL;
        if (tail) tail->next = node;
        else head = node;
        tail = node;
    }
    std::vector<int> out = dll_backward(head);
    for (size_t i = 0; i < out.size(); i++) {
        if (i) std::cout << ' ';
        std::cout << out[i];
    }
    std::cout << "\n";
    return 0;
}

