bool badge_symmetric(const std::string &code) {
    int i = 0, j = (int)code.size() - 1;
    while (i < j) {
        char a = code[i], b = code[j];
        if (a >= 'A' && a <= 'Z') a = (char)(a - 'A' + 'a');
        if (b >= 'A' && b <= 'Z') b = (char)(b - 'A' + 'a');
        if (a != b) return false;
        i++;
        j--;
    }
    return true;
}

int main() {
    std::string code;
    std::cin >> code;
    std::cout << badge_symmetric(code) << std::endl;
    return 0;
}

