int balance_index(const std::vector<long long>& a) {
    long long total = 0;
    for (long long v : a) total += v;
    long long leftSum = 0;
    for (size_t i = 0; i < a.size(); i++) {
        if (leftSum == total - leftSum - a[i]) return (int)i;
        leftSum += a[i];
    }
    return -1;
}

int main() {
    long long n;
    std::cin >> n;
    std::vector<long long> a(n);
    for (long long i = 0; i < n; i++) std::cin >> a[i];
    std::cout << balance_index(a) << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <stack>

bool is_balanced(const std::string &s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') {
            st.push(c);
        } else {
            if (st.empty()) return false;
            char t = st.top();
            st.pop();
            if (c == ')' && t != '(') return false;
            if (c == ']' && t != '[') return false;
            if (c == '}' && t != '{') return false;
        }
    }
    return st.empty();
}

int main() {
    std::string s;
    std::cin >> s;
    std::cout << (is_balanced(s) ? 1 : 0) << std::endl;
    return 0;
}

