long long max_subarray_sum(const std::vector<long long>& a) {
    long long cur = a[0];
    long long best = a[0];
    for (size_t i = 1; i < a.size(); i++) {
        if (cur + a[i] < a[i]) cur = a[i];
        else cur = cur + a[i];
        if (cur > best) best = cur;
    }
    return best;
}

