    int n;
    std::cin >> n;
    std::vector<int> v(n);
    for (int &x : v) std::cin >> x;
    int target;
    std::cin >> target;
    std::cout << binary_search_idx(v, target) << std::endl;
    return 0;
}

// Bottom-Up Merge Sort (widths 1, 2, 4, ...; no recursion)
#include <iostream>
#include <vector>
using namespace std;

vector<int> bottom_up_merge(vector<int> v) {
    int n = (int)v.size();
    vector<int> t(n);
    int width = 1;
    while (width < n) {
        for (int lo = 0; lo < n; lo += 2 * width) {
            int mid = lo + width < n ? lo + width : n;
            int hi = lo + 2 * width < n ? lo + 2 * width : n;
            int i = lo, j = mid, k = lo;
            while (i < mid && j < hi)
                t[k++] = v[i] <= v[j] ? v[i++] : v[j++];
            while (i < mid) t[k++] = v[i++];
            while (j < hi) t[k++] = v[j++];
        }
        for (int i = 0; i < n; i++) v[i] = t[i];
        width *= 2;
    }
    return v;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    vector<int> res = bottom_up_merge(v);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

#include <iostream>
