#include <queue>

int reachable_count(int V, const std::vector<std::vector<int>>& adj, int start) {
    std::vector<int> visited(V, 0);
    std::queue<int> q;
    q.push(start);
    visited[start] = 1;
    int c = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        c++;
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (!visited[v]) {
                visited[v] = 1;
                q.push(v);
            }
        }
    }
    return c;
}

int main() {
    int V, E;
    std::cin >> V >> E;
    std::vector<std::vector<int>> adj(V);
    for (int i = 0; i < E; i++) {
        int u, v;
        std::cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int start;
    std::cin >> start;
    std::cout << reachable_count(V, adj, start) << "\n";
    return 0;
}

