// Bubble Sort Swap Count (equals the number of inversions)
#include <iostream>
#include <vector>
using namespace std;

int bubble_swaps(vector<int> v) {
    int n = (int)v.size(), swaps = 0;
    for (int p = 0; p < n - 1; p++)
        for (int j = 0; j < n - 1 - p; j++)
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
                swaps++;
            }
    return swaps;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << bubble_swaps(v) << "\n";
    return 0;
}

