vector<int> bubble_sort(vector<int> v) {
    int n = (int)v.size();
    for (int p = 0; p < n - 1; p++)
        for (int j = 0; j < n - 1 - p; j++)
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
