bool dfs_cycle(int u, const std::vector<std::vector<int>>& adj, std::vector<int>& state) {
    state[u] = 1;
    for (size_t i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (state[v] == 1) return true;
        if (state[v] == 0 && dfs_cycle(v, adj, state)) return true;
    }
    state[u] = 2;
    return false;
}

int has_cycle(int V, const std::vector<std::vector<int>>& adj) {
    std::vector<int> state(V, 0);
    for (int i = 0; i < V; i++)
        if (state[i] == 0 && dfs_cycle(i, adj, state)) return 1;
    return 0;
}

int main() {
    int V, E;
    std::cin >> V >> E;
    std::vector<std::vector<int>> adj(V);
    for (int i = 0; i < E; i++) {
        int u, v;
        std::cin >> u >> v;
        adj[u].push_back(v);
    }
    std::cout << has_cycle(V, adj) << "\n";
    return 0;
}

#include <iostream>
#include <vector>

void build_min_heap(std::vector<int>& heap) {
    int n = (int)heap.size();
    for (int start = n / 2 - 1; start >= 0; start--) {
        int i = start;
        while (true) {
            int l = 2 * i + 1;
            int r = 2 * i + 2;
            int small = i;
            if (l < n && heap[l] < heap[small]) small = l;
            if (r < n && heap[r] < heap[small]) small = r;
            if (small == i) break;
            int tmp = heap[i];
            heap[i] = heap[small];
            heap[small] = tmp;
            i = small;
        }
    }
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> heap(n);
    for (int i = 0; i < n; i++) std::cin >> heap[i];
    build_min_heap(heap);
    for (int i = 0; i < n; i++) {
        if (i) std::cout << ' ';
        std::cout << heap[i];
    }
    std::cout << "\n";
    return 0;
}

