std::string caesar_shift(const std::string &s, int k) {
    k %= 26;
    std::string out;
    for (char c : s) {
        if (c >= 'a' && c <= 'z') out += (char)('a' + (c - 'a' + k) % 26);
        else if (c >= 'A' && c <= 'Z') out += (char)('A' + (c - 'A' + k) % 26);
        else out += c;
    }
    return out;
}

int main() {
    std::string s;
    int k;
    std::cin >> s >> k;
    std::cout << caesar_shift(s, k) << std::endl;
    return 0;
}

