#include <iostream>
#include <cstddef>

struct DNode {
    int data;
    DNode* prev;
    DNode* next;
};

int ring_length(DNode* head) {
    int count = 1;
    DNode* cur = head;
    while (cur->next != head) {
        cur = cur->next;
        count++;
    }
    return count;
}

int main() {
    int n;
    std::cin >> n;
    DNode* head = NULL;
    DNode* tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        DNode* node = new DNode();
        node->data = v;
        if (!head) {
            node->next = node;
            node->prev = node;
            head = node;
        } else {
            node->prev = tail;
            node->next = head;
            tail->next = node;
            head->prev = node;
        }
        tail = node;
    }
    std::cout << ring_length(head) << "\n";
    return 0;
}

