int case_cmp(const std::string &a, const std::string &b) {
    std::string la, lb;
    for (char c : a) {
        if (c >= 'A' && c <= 'Z') c = (char)(c - 'A' + 'a');
        la += c;
    }
    for (char c : b) {
        if (c >= 'A' && c <= 'Z') c = (char)(c - 'A' + 'a');
        lb += c;
    }
    if (la < lb) return -1;
    if (lb < la) return 1;
    return 0;
}

int main() {
    std::string a, b;
    std::cin >> a >> b;
    std::cout << case_cmp(a, b) << std::endl;
    return 0;
}

