// Comparison Duel: Merge vs Quick (exact counting rules)
#include <iostream>
#include <vector>
using namespace std;

long long merge_dual(vector<int> &v, int lo, int mid, int hi) {
    vector<int> t;
    int i = lo, j = mid;
    long long c = 0;
    while (i < mid && j < hi) {
        c++;
        if (v[i] <= v[j]) {
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
        }
    }
    while (i < mid) {
        t.push_back(v[i]);
        i++;
    }
    while (j < hi) {
        t.push_back(v[j]);
        j++;
    }
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
    return c;
}

long long msort_dual(vector<int> &v, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    return msort_dual(v, lo, mid) + msort_dual(v, mid, hi) +
           merge_dual(v, lo, mid, hi);
}

int qs_dual(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

long long qsort_dual(vector<int> &v, int lo, int hi) {
    if (hi - lo + 1 <= 1) return 0;
    int p = qs_dual(v, lo, hi);
    return (hi - lo) + qsort_dual(v, lo, p - 1) + qsort_dual(v, p + 1, hi);
}

void compare_counts(vector<int> v, long long &mergeComp, long long &quickComp) {
    mergeComp = msort_dual(v, 0, (int)v.size());
    quickComp = qsort_dual(v, 0, (int)v.size() - 1);
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    long long mc = 0, qc = 0;
    compare_counts(v, mc, qc);
    cout << mc << ' ' << qc << "\n";
    return 0;
}

// Comparisons for Early-Stop Bubble (full scans; stop after a no-swap pass)
#include <iostream>
#include <vector>
using namespace std;

int bubble_comparisons(vector<int> v) {
    int n = (int)v.size(), comps = 0;
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (int j = 0; j < n - 1; j++) {
            comps++;
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
                swapped = true;
            }
        }
    }
    return comps;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << bubble_comparisons(v) << "\n";
    return 0;
}

