int build_swap_count(std::vector<int> v) {
    int n = (int)v.size();
    int swaps = 0;
    for (int start = n / 2 - 1; start >= 0; start--) {
        int i = start;
        while (true) {
            int l = 2 * i + 1;
            int r = 2 * i + 2;
            int small = i;
            if (l < n && v[l] < v[small]) small = l;
            if (r < n && v[r] < v[small]) small = r;
            if (small == i) break;
            int tmp = v[i];
            v[i] = v[small];
            v[small] = tmp;
            swaps++;
            i = small;
        }
    }
    return swaps;
}

