    DNode* next;
};

DNode* dll_delete_value(DNode* head, int value) {
    DNode* cur = head;
    while (cur && cur->data != value) cur = cur->next;
    if (!cur) return head;
    if (cur->prev) cur->prev->next = cur->next;
    else head = cur->next;
    if (cur->next) cur->next->prev = cur->prev;
    return head;
}

