#include <iostream>

struct TNode {
    int val;
    TNode* left;
    TNode* right;
    TNode() : val(0), left(NULL), right(NULL) {}
};

TNode* bst_insert(TNode* root, int value) {
    if (!root) {
        TNode* node = new TNode();
        node->val = value;
        node->left = NULL;
        node->right = NULL;
        return node;
    }
    if (value < root->val) root->left = bst_insert(root->left, value);
    else if (value > root->val) root->right = bst_insert(root->right, value);
    return root;
}

void inorder_print(TNode* root, bool& first) {
    if (!root) return;
    inorder_print(root->left, first);
    if (!first) std::cout << ' ';
    std::cout << root->val;
    first = false;
    inorder_print(root->right, first);
}

TNode* bst_delete(TNode* root, int value) {
    if (!root) return NULL;
    if (value < root->val) {
        root->left = bst_delete(root->left, value);
    } else if (value > root->val) {
        root->right = bst_delete(root->right, value);
    } else {
        if (!root->left) {
            TNode* r = root->right;
            delete root;
            return r;
        }
        if (!root->right) {
            TNode* l = root->left;
            delete root;
            return l;
        }
        TNode* succ = root->right;
        while (succ->left) succ = succ->left;
        root->val = succ->val;
        root->right = bst_delete(root->right, succ->val);
    }
    return root;
}

int main() {
    int n;
    std::cin >> n;
    TNode* root = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        root = bst_insert(root, v);
    }
    int value;
    std::cin >> value;
    root = bst_delete(root, value);
    bool first = true;
    inorder_print(root, first);
    std::cout << "\n";
    return 0;
}

