int count_at_hops(int V, const std::vector<std::vector<int>>& adj, int src, int k) {
    std::vector<int> dist(V, -1);
    std::queue<int> q;
    dist[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    int c = 0;
    for (int i = 0; i < V; i++)
        if (dist[i] == k) c++;
    return c;
}

