#include <queue>

int farthest_node(int V, const std::vector<std::vector<int>>& adj, int src) {
    std::vector<int> dist(V, -1);
    std::queue<int> q;
    dist[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    int best = src;
    for (int i = 0; i < V; i++)
        if (dist[i] > dist[best]) best = i;
    return best;
}

int main() {
    int V, E;
    std::cin >> V >> E;
    std::vector<std::vector<int>> adj(V);
    for (int i = 0; i < E; i++) {
        int u, v;
        std::cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int src;
    std::cin >> src;
    std::cout << farthest_node(V, adj, src) << "\n";
    return 0;
}

