// Full Bubble Sort Flight Recorder (state after every pass, incl. final)
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    bool swapped = true;
    while (swapped) {
        swapped = false;
        for (int j = 0; j < n - 1; j++)
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
                swapped = true;
            }
        for (int i = 0; i < n; i++)
            cout << v[i] << (i + 1 < n ? ' ' : '\n');
    }
    return 0;
}

