// Hoare Partition Point (pivot captured once from the first element)
#include <iostream>
#include <vector>
using namespace std;

int hoare_partition(vector<int> &v) {
    int n = (int)v.size();
    int pivot = v[0], i = -1, j = n;
    while (true) {
        do { i++; } while (v[i] < pivot);
        do { j--; } while (v[j] > pivot);
        if (i >= j) return j;
        int t = v[i];
        v[i] = v[j];
        v[j] = t;
    }
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    int j = hoare_partition(v);
    cout << j << "\n";
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

