void hop_distances(int V, const std::vector<std::vector<int>>& adj, int src, std::vector<int>& out) {
    out.assign(V, -1);
    std::queue<int> q;
    out[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (out[v] == -1) {
                out[v] = out[u] + 1;
                q.push(v);
            }
        }
    }
}

