std::vector<int> elimination_order(int n, int k) {
    std::queue<int> q;
    for (int p = 1; p <= n; p++) q.push(p);
    std::vector<int> out;
    while (!q.empty()) {
        for (int hop = 0; hop < k - 1; hop++) {
            q.push(q.front());
            q.pop();
        }
        out.push_back(q.front());
        q.pop();
    }
    return out;
}

