void reverse_range(std::vector<int> &v, int l, int r) {
    while (l < r) {
        int t = v[l];
        v[l] = v[r];
        v[r] = t;
        l++;
        r--;
    }
}

void rotate_inplace(std::vector<int> &v, int k) {
    int n = (int)v.size();
    if (n == 0) return;
    k %= n;
    reverse_range(v, 0, k - 1);
    reverse_range(v, k, n - 1);
    reverse_range(v, 0, n - 1);
}

