                bq[tail++] = c;
            }
            i++;
        }
        if (i < nv) {
            if (vals[i] != -1) {
                TNode* c = new TNode(vals[i]);
                cur->right = c;
                bq[tail++] = c;
            }
            i++;
        }
    }
    return root;
}

void inorder(TNode* root, std::vector<int>& out) {
    if (!root) return;
    inorder(root->left, out);
    out.push_back(root->val);
    inorder(root->right, out);
}

