// Insertion Sort Shift Count
#include <iostream>
#include <vector>
using namespace std;

int insertion_shifts(vector<int> v) {
    int shifts = 0;
    for (int i = 1; i < (int)v.size(); i++) {
        int key = v[i], j = i - 1;
        while (j >= 0 && v[j] > key) {
            v[j + 1] = v[j];
            j--;
            shifts++;
        }
        v[j + 1] = key;
    }
    return shifts;
}

