int is_tree(int V, const std::vector<std::vector<int>>& adj) {
    int edges = 0;
    for (int i = 0; i < V; i++) edges += (int)adj[i].size();
    if (edges / 2 != V - 1) return 0;
    std::vector<int> visited(V, 0);
    dfs_visit(0, adj, visited);
    for (int i = 0; i < V; i++)
        if (!visited[i]) return 0;
    return 1;
}

