    DNode* prev;
    DNode* next;
};

int ring_size(DNode* head) {
    int count = 1;
    DNode* cur = head;
    while (cur->next != head) {
        cur = cur->next;
        count++;
    }
    return count;
}

int josephus_survivor(DNode* head, int k) {
    DNode* prev = head;
    while (prev->next != head) prev = prev->next;
    DNode* cur = head;
    int remaining = ring_size(head);
    while (remaining > 1) {
        for (int step = 1; step < k; step++) {
            prev = cur;
            cur = cur->next;
        }
        prev->next = cur->next;
        cur->next->prev = prev;
        cur = cur->next;
        remaining--;
    }
    return cur->data;
}

