int last_occurrence(const std::vector<int> &v, int target) {
    int lo = 0, hi = (int)v.size() - 1, ans = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == target) { ans = mid; lo = mid + 1; }
        else if (v[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return ans;
}

