#include <iostream>
#include <vector>
using namespace std;

int lomuto_partition(vector<int> &v) {
    int n = (int)v.size();
    int pivot = v[n - 1], i = -1;
    for (int j = 0; j < n - 1; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[n - 1];
    v[n - 1] = t;
    return i + 1;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    int p = lomuto_partition(v);
    cout << p << "\n";
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

