int longest_budget_streak(const std::vector<long long>& cost, long long budget) {
    long long sum = 0;
    int left = 0, best = 0;
    for (int right = 0; right < (int)cost.size(); right++) {
        sum += cost[right];
        while (sum > budget && left <= right) {
            sum -= cost[left];
            left++;
        }
        if (right - left + 1 > best) best = right - left + 1;
    }
    return best;
}

int main() {
    long long n, budget;
    std::cin >> n >> budget;
    std::vector<long long> cost(n);
    for (long long i = 0; i < n; i++) std::cin >> cost[i];
    std::cout << longest_budget_streak(cost, budget) << "\n";
    return 0;
}

