    Node* tail2 = &dummy;
    while (a && b) {
        if (a->data <= b->data) {
            tail2->next = a;
            a = a->next;
        } else {
            tail2->next = b;
            b = b->next;
        }
        tail2 = tail2->next;
    }
    tail2->next = a ? a : b;
    return dummy.next;
}
Node* merge_sort_list(Node* head) {
    if (!head || !head->next) return head;
    Node* slow = head;
    Node* fast = head->next;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    Node* mid = slow->next;
    slow->next = NULL;
    return merge_two(merge_sort_list(head), merge_sort_list(mid));
}

