    vector<int> t;
    int i = lo, j = mid;
    while (i < mid && j < hi) {
        if (v[i] <= v[j]) {
            t.push_back(v[i]);
            i++;
        } else {
            t.push_back(v[j]);
            j++;
        }
        steps++;
    }
    while (i < mid) {
        t.push_back(v[i]);
        i++;
        steps++;
    }
    while (j < hi) {
        t.push_back(v[j]);
        j++;
        steps++;
    }
    for (int k = 0; k < (int)t.size(); k++) v[lo + k] = t[k];
