#include <queue>

int shortest_hops(int V, const std::vector<std::vector<int>>& adj, int src, int dst) {
    if (src == dst) return 0;
    std::vector<int> dist(V, -1);
    std::queue<int> q;
    dist[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (v == dst) return dist[v];
                q.push(v);
            }
        }
    }
    return -1;
}

int main() {
    int V, E;
    std::cin >> V >> E;
    std::vector<std::vector<int>> adj(V);
    for (int i = 0; i < E; i++) {
        int u, v;
        std::cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    int src, dst;
    std::cin >> src >> dst;
    std::cout << shortest_hops(V, adj, src, dst) << "\n";
    return 0;
}

