    dp[0] = 0;
    for (int i = 1; i < n; i++)
        for (int j = 0; j < i; j++)
            if (dp[j] != -1 && j + arr[j] >= i) {
                if (dp[i] == -1 || dp[j] + 1 < dp[i]) dp[i] = dp[j] + 1;
            }
    return dp[n - 1];
}

