long long days_needed(const std::vector<int> &w, long long cap) {
    long long days = 1, load = 0;
    for (int x : w) {
        if (load + x > cap) {
            days++;
            load = x;
        } else {
            load += x;
        }
    }
    return days;
}

long long min_capacity(const std::vector<int> &w, int days) {
    long long lo = 0, hi = 0;
    for (int x : w) {
        if (x > lo) lo = x;
        hi += x;
    }
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (days_needed(w, mid) <= days) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}

