std::vector<int> next_greater(const std::vector<int> &a) {
    int n = (int)a.size();
    std::vector<int> ans(n, -1);
    std::stack<int> st;
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty() && st.top() <= a[i]) st.pop();
        if (!st.empty()) ans[i] = st.top();
        st.push(a[i]);
    }
    return ans;
}

