int min_hops(int V, const std::vector<std::vector<int>>& adj, int src, int dst) {
    if (src == dst) return 0;
    std::vector<int> dist(V, -1);
    std::queue<int> q;
    dist[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (size_t i = 0; i < adj[u].size(); i++) {
            int v = adj[u][i];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                if (v == dst) return dist[v];
                q.push(v);
            }
        }
    }
    return -1;
}

int parcel_hops(int V, const std::vector<std::vector<int>>& adj, int src, int dst) {
    return min_hops(V, adj, src, dst);
}

