// Partition the Audit Trail (one Lomuto pass, last entry as pivot)
#include <iostream>
#include <vector>
using namespace std;

int audit_partition(vector<int> &v) {
    int n = (int)v.size();
    int pivot = v[n - 1], i = -1;
    for (int j = 0; j < n - 1; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[n - 1];
    v[n - 1] = t;
    return i + 1;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    int p = audit_partition(v);
    cout << p << "\n";
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Passes Until the Deck Is Sorted (includes the final no-swap pass)
#include <iostream>
#include <vector>
using namespace std;

int bubble_passes(vector<int> v) {
    int n = (int)v.size(), passes = 0;
    bool swapped = true;
    while (swapped) {
        swapped = false;
        passes++;
        for (int j = 0; j < n - 1; j++)
            if (v[j] > v[j + 1]) {
                int t = v[j];
                v[j] = v[j + 1];
                v[j + 1] = t;
                swapped = true;
            }
    }
    return passes;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << bubble_passes(v) << "\n";
    return 0;
}

