std::vector<int> pop_min(std::vector<int> heap) {
    int n = (int)heap.size();
    heap[0] = heap[n - 1];
    heap.pop_back();
    int i = 0;
    int m = (int)heap.size();
    while (true) {
        int l = 2 * i + 1;
        int r = 2 * i + 2;
        int small = i;
        if (l < m && heap[l] < heap[small]) small = l;
        if (r < m && heap[r] < heap[small]) small = r;
        if (small == i) break;
        int tmp = heap[i];
        heap[i] = heap[small];
        heap[small] = tmp;
        i = small;
    }
    return heap;
}

