// Quicksort Pivot Flight Recorder (Lomuto, last element as pivot,
// left side recursed first)
#include <iostream>
#include <vector>
using namespace std;

int lomuto_trace(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

void qs_trace(vector<int> &v, int lo, int hi, vector<int> &pivots) {
    if (hi - lo + 1 <= 1) return;
    int p = lomuto_trace(v, lo, hi);
    pivots.push_back(p);
    qs_trace(v, lo, p - 1, pivots);
    qs_trace(v, p + 1, hi, pivots);
}

void quicksort_trace(vector<int> &v, vector<int> &pivots) {
    pivots.clear();
    qs_trace(v, 0, (int)v.size() - 1, pivots);
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    vector<int> pivots;
    quicksort_trace(v, pivots);
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    for (int i = 0; i < (int)pivots.size(); i++)
        cout << pivots[i] << (i + 1 < (int)pivots.size() ? ' ' : '\n');
    return 0;
}

// Quicksort a Vector (Lomuto, last element as pivot)
#include <iostream>
#include <vector>
using namespace std;

int qsort_partition(vector<int> &v, int lo, int hi) {
    int pivot = v[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (v[j] <= pivot) {
            i++;
            int t = v[i];
            v[i] = v[j];
            v[j] = t;
        }
    int t = v[i + 1];
    v[i + 1] = v[hi];
    v[hi] = t;
    return i + 1;
}

void qsort_rec(vector<int> &v, int lo, int hi) {
    if (lo >= hi) return;
    int p = qsort_partition(v, lo, hi);
    qsort_rec(v, lo, p - 1);
    qsort_rec(v, p + 1, hi);
}

vector<int> quick_sort(vector<int> v) {
    qsort_rec(v, 0, (int)v.size() - 1);
    return v;
}

int main() {
    int n;
