#include <cstddef>

struct DNode {
    int data;
    DNode* prev;
    DNode* next;
};

DNode* ring_delete(DNode* head, int value) {
    if (head->data == value) {
        DNode* last = head;
        while (last->next != head) last = last->next;
        DNode* new_head = head->next;
        last->next = new_head;
        new_head->prev = last;
        return new_head;
    }
    DNode* cur = head;
    while (cur->next->data != value) cur = cur->next;
    DNode* victim = cur->next;
    cur->next = victim->next;
    victim->next->prev = cur;
    return head;
}

int main() {
    int n;
    std::cin >> n;
    DNode* head = NULL;
    DNode* tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        DNode* node = new DNode();
        node->data = v;
        if (!head) {
            node->next = node;
            node->prev = node;
            head = node;
        } else {
            node->prev = tail;
            node->next = head;
            tail->next = node;
            head->prev = node;
        }
        tail = node;
    }
    int value;
    std::cin >> value;
    DNode* res = ring_delete(head, value);
    DNode* cur = res;
    bool first = true;
    if (res) {
        do {
            if (!first) std::cout << ' ';
            std::cout << cur->data;
            first = false;
            cur = cur->next;
        } while (cur != res);
    }
    std::cout << "\n";
    return 0;
}

