struct Node {
    int data;
    Node* next;
};

Node* rotate_list(Node* head, int k) {
    if (!head || !head->next || k == 0) return head;
    int count = 1;
    Node* tail = head;
    while (tail->next) {
        tail = tail->next;
        count++;
    }
    k %= count;
    if (k == 0) return head;
    tail->next = head;
    Node* cur = head;
    for (int i = 0; i < count - k - 1; i++) cur = cur->next;
    Node* new_head = cur->next;
    cur->next = NULL;
    return new_head;
}

