std::vector<int> rotate_queue(std::vector<int> q, int k) {
    std::queue<int> qu;
    for (int x : q) qu.push(x);
    for (int i = 0; i < k; i++) {
        qu.push(qu.front());
        qu.pop();
    }
    std::vector<int> out;
    while (!qu.empty()) {
        out.push_back(qu.front());
        qu.pop();
    }
    return out;
}

