std::vector<int> rotate_k(const std::vector<int> &v, int k) {
    int n = (int)v.size();
    std::vector<int> out;
    out.reserve(n);
    for (int i = 0; i < n; i++)
        out.push_back(v[(i + (long long)k) % n]);
    return out;
}

