int rotation_point(const std::vector<int> &v) {
    int lo = 0, hi = (int)v.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] > v[hi]) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

