#include <iostream>
#include <string>

std::string compress_runs(const std::string &s) {
    std::string out;
    int i = 0;
    while (i < (int)s.size()) {
        int j = i;
        while (j < (int)s.size() && s[j] == s[i]) j++;
        int runLen = j - i;
        out += s[i];
        if (runLen > 1) out += std::to_string(runLen);
        i = j;
    }
    return out;
}

int main() {
    std::string s;
    std::cin >> s;
    std::cout << compress_runs(s) << std::endl;
    return 0;
}

