struct TNode {
    int val;
    TNode* left;
    TNode* right;
    TNode() : val(0), left(NULL), right(NULL) {}
};

TNode* bst_insert(TNode* root, int value) {
    if (!root) {
        TNode* node = new TNode();
        node->val = value;
        node->left = NULL;
        node->right = NULL;
        return node;
    }
    if (value < root->val) root->left = bst_insert(root->left, value);
    else if (value > root->val) root->right = bst_insert(root->right, value);
    return root;
}

std::vector<int> search_path(TNode* root, int target) {
    std::vector<int> path;
    TNode* cur = root;
    while (cur) {
        path.push_back(cur->val);
        if (target == cur->val) break;
        if (target < cur->val) cur = cur->left;
        else cur = cur->right;
    }
    return path;
}

int main() {
    int n;
    std::cin >> n;
    TNode* root = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        root = bst_insert(root, v);
    }
    int target;
    std::cin >> target;
    std::vector<int> res = search_path(root, target);
    for (int i = 0; i < (int)res.size(); i++) {
        if (i) std::cout << ' ';
        std::cout << res[i];
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>

struct TNode {
    int val;
    TNode* left;
    TNode* right;
    TNode() : val(0), left(NULL), right(NULL) {}
};

TNode* bst_insert(TNode* root, int value) {
    if (!root) {
        TNode* node = new TNode();
        node->val = value;
        node->left = NULL;
        node->right = NULL;
        return node;
    }
    if (value < root->val) root->left = bst_insert(root->left, value);
    else if (value > root->val) root->right = bst_insert(root->right, value);
    return root;
}

bool bst_search(TNode* root, int target) {
    while (root) {
        if (target == root->val) return true;
        if (target < root->val) root = root->left;
        else root = root->right;
    }
    return false;
}

