// Selection Sort Swap Count
#include <iostream>
#include <vector>
using namespace std;

int selection_swaps(vector<int> v) {
    int n = (int)v.size(), swaps = 0;
    for (int i = 0; i < n - 1; i++) {
        int m = i;
        for (int j = i + 1; j < n; j++)
            if (v[j] < v[m]) m = j;
        if (m != i) {
            int t = v[i];
            v[i] = v[m];
            v[m] = t;
            swaps++;
        }
    }
    return swaps;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << selection_swaps(v) << "\n";
    return 0;
}

