#include <iostream>

struct Node {
    int data;
    Node* next;
};

int longest_streak(Node* head) {
    int best = 0, run = 0;
    int prev_val = 0;
    bool has_prev = false;
    for (Node* cur = head; cur != NULL; cur = cur->next) {
        if (has_prev && cur->data == prev_val) run++;
        else run = 1;
        if (run > best) best = run;
        prev_val = cur->data;
        has_prev = true;
    }
    return best;
}

int main() {
    int n;
    std::cin >> n;
    Node* head = NULL;
    Node* tail = NULL;
    for (int i = 0; i < n; i++) {
        int x;
        std::cin >> x;
        Node* nd = new Node();
        nd->data = x;
        nd->next = NULL;
        if (!head) head = nd;
        else tail->next = nd;
        tail = nd;
    }
    std::cout << longest_streak(head) << std::endl;
    return 0;
}

