}

// Shelf by Popularity Then Label
// Order values by frequency descending, breaking ties by value ascending.
#include <iostream>
#include <vector>
using namespace std;

int freq_of(const vector<int> &v, int x) {
    int f = 0;
    for (int y : v)
        if (y == x) f++;
    return f;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];

    for (int i = 0; i < n - 1; i++) {      // manual selection ordering
        int m = i, mf = freq_of(v, v[i]);
        for (int j = i + 1; j < n; j++) {
            int f = freq_of(v, v[j]);
            if (f > mf || (f == mf && v[j] < v[m])) {
                m = j;
                mf = f;
            }
        }
        if (m != i) {
            int t = v[i];
            v[i] = v[m];
            v[m] = t;
        }
    }
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Shifts on a Nearly Sorted Price List (insertion shift count)
#include <iostream>
#include <vector>
using namespace std;

int price_shifts(vector<int> v) {
    int shifts = 0;
    for (int i = 1; i < (int)v.size(); i++) {
        int key = v[i], j = i - 1;
        while (j >= 0 && v[j] > key) {
            v[j + 1] = v[j];
            j--;
            shifts++;
        }
        v[j + 1] = key;
    }
    return shifts;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    cout << price_shifts(v) << "\n";
    return 0;
}

