std::vector<int> sift_up(std::vector<int> heap) {
    int i = (int)heap.size() - 1;
    while (i > 0 && heap[i] < heap[(i - 1) / 2]) {
        int p = (i - 1) / 2;
        int tmp = heap[i];
        heap[i] = heap[p];
        heap[p] = tmp;
        i = p;
    }
    return heap;
}

