#include <iostream>
#include <string>
#include <stack>

std::string simplify_path(const std::string &path) {
    std::stack<std::string> st;
    std::string cur;
    for (size_t i = 0; i <= path.size(); i++) {
        char c = (i < path.size()) ? path[i] : '/';
        if (c == '/') {
            if (!cur.empty() && cur != ".") {
                if (cur == "..") {
                    if (!st.empty()) st.pop();
                } else {
                    st.push(cur);
                }
            }
            cur.clear();
        } else {
            cur += c;
        }
    }
    std::stack<std::string> rev;
    while (!st.empty()) {
        rev.push(st.top());
        st.pop();
    }
    std::string out;
    while (!rev.empty()) {
        out += '/';
        out += rev.top();
        rev.pop();
    }
    if (out.empty()) out = "/";
    return out;
}

int main() {
    std::string path;
    std::cin >> path;
    std::cout << simplify_path(path) << std::endl;
    return 0;
}

