long long max_window_sum(const std::vector<int> &v, int w) {
    long long sum = 0;
    for (int i = 0; i < w; i++) sum += v[i];
    long long best = sum;
    for (int i = w; i < (int)v.size(); i++) {
        sum += v[i] - v[i - w];
        if (sum > best) best = sum;
    }
    return best;
}

