struct TNode {
    int val;
    TNode* left;
    TNode* right;
    TNode() : val(0), left(NULL), right(NULL) {}
};

TNode* bst_insert(TNode* root, int value) {
    if (!root) {
        TNode* node = new TNode();
        node->val = value;
        node->left = NULL;
        node->right = NULL;
        return node;
    }
    if (value < root->val) root->left = bst_insert(root->left, value);
    else if (value > root->val) root->right = bst_insert(root->right, value);
    return root;
}

int bst_ceiling(TNode* root, int target) {
    int best = -1;
    while (root) {
        if (root->val == target) return root->val;
        if (root->val > target) {
            best = root->val;
            root = root->left;
        } else {
            root = root->right;
        }
    }
    return best;
}

