std::vector<int> sort_stack(std::vector<int> st) {
    std::stack<int> input;
    for (int x : st) input.push(x);
    std::stack<int> aux;
    while (!input.empty()) {
        int temp = input.top();
        input.pop();
        while (!aux.empty() && aux.top() < temp) {
            input.push(aux.top());
            aux.pop();
        }
        aux.push(temp);
    }
    std::vector<int> out;
    while (!aux.empty()) {
        out.push_back(aux.top());
        aux.pop();
    }
    return out;
}

