struct DNode {
    int data;
    DNode* prev;
    DNode* next;
};

DNode* ring_insert_sorted(DNode* head, int value) {
    DNode* node = new DNode();
    node->data = value;
    node->prev = NULL;
    node->next = NULL;
    if (value < head->data) {
        DNode* last = head;
        while (last->next != head) last = last->next;
        last->next = node;
        node->prev = last;
        node->next = head;
        head->prev = node;
        return node;
    }
    DNode* cur = head;
    while (cur->next != head && cur->next->data < value) cur = cur->next;
    node->next = cur->next;
    node->prev = cur;
    cur->next->prev = node;
    cur->next = node;
    return head;
}

int main() {
    int n;
    std::cin >> n;
    DNode* head = NULL;
    DNode* tail = NULL;
    for (int i = 0; i < n; i++) {
        int v;
        std::cin >> v;
        DNode* node = new DNode();
        node->data = v;
        if (!head) {
            node->next = node;
            node->prev = node;
            head = node;
        } else {
            node->prev = tail;
            node->next = head;
            tail->next = node;
            head->prev = node;
        }
        tail = node;
    }
    int value;
    std::cin >> value;
    DNode* res = ring_insert_sorted(head, value);
    DNode* cur = res;
    bool first = true;
    if (res) {
        do {
            if (!first) std::cout << ' ';
            std::cout << cur->data;
            first = false;
            cur = cur->next;
        } while (cur != res);
    }
    std::cout << "\n";
    return 0;
}

