void split_letters(const std::string &s, std::string &vowels, std::string &consonants) {
    vowels = "";
    consonants = "";
    for (char c : s) {
        char low = c;
        if (low >= 'A' && low <= 'Z') low = (char)(low - 'A' + 'a');
        bool isVowel =
            low == 'a' || low == 'e' || low == 'i' || low == 'o' || low == 'u';
        bool isLetter = (low >= 'a' && low <= 'z');
        if (!isLetter) continue;
        if (isVowel) vowels += c;
        else consonants += c;
    }
}

