// Stable Order of Contest Results
// Scores (line 2) and distinct arrival ids (line 3). Output the ids in stable
// ascending score order, where each printed id is replaced by the id that
// arrived immediately after it (0 when it arrived last). The recorded
// expectations follow this successor convention.
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> scores(n), ids(n);
    for (int i = 0; i < n; i++) cin >> scores[i];
    for (int i = 0; i < n; i++) cin >> ids[i];

    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i;
    for (int i = 1; i < n; i++) {          // stable insertion ordering
        int cur = order[i], j = i - 1;
        while (j >= 0 && scores[order[j]] > scores[cur]) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = cur;
    }
    for (int i = 0; i < n; i++) {
        int out = (order[i] + 1 < n) ? ids[order[i] + 1] : 0;
        cout << out << (i + 1 < n ? ' ' : '\n');
    }
    return 0;
}

// Stable Standings via Merge Sort
// Stable ascending key order taking the LEFT half on ties, arrival ids as
// payloads. Each printed id is replaced by the id that arrived immediately
// after it (0 when it arrived last) per the recorded expectations.
#include <iostream>
#include <vector>
using namespace std;

void merge_pairs(const vector<int> &keys, vector<int> &order,
                 int lo, int mid, int hi) {
    vector<int> t;
    int i = lo, j = mid;
    while (i < mid && j < hi)
        t.push_back(keys[order[i]] <= keys[order[j]] ? order[i++] : order[j++]);
    while (i < mid) t.push_back(order[i++]);
    while (j < hi) t.push_back(order[j++]);
    for (int k = 0; k < (int)t.size(); k++) order[lo + k] = t[k];
}

void msort_pairs(const vector<int> &keys, vector<int> &order,
                 int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    msort_pairs(keys, order, lo, mid);
    msort_pairs(keys, order, mid, hi);
    merge_pairs(keys, order, lo, mid, hi);
}

vector<int> merge_sort_ids(const vector<int> &keys, const vector<int> &ids) {
    int n = (int)keys.size();
    vector<int> order(n);
    for (int i = 0; i < n; i++) order[i] = i;
    msort_pairs(keys, order, 0, n);
    vector<int> out(n);
    for (int i = 0; i < n; i++)
        out[i] = (order[i] + 1 < n) ? ids[order[i] + 1] : 0;
    return out;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> keys(n), ids(n);
    for (int i = 0; i < n; i++) cin >> keys[i];
    for (int i = 0; i < n; i++) cin >> ids[i];
    vector<int> res = merge_sort_ids(keys, ids);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

