std::vector<int> stock_span(const std::vector<int> &prices) {
    int n = (int)prices.size();
    std::vector<int> spans(n);
    std::stack<int> st;
    for (int i = 0; i < n; i++) {
        while (!st.empty() && prices[st.top()] <= prices[i]) st.pop();
        spans[i] = st.empty() ? (i + 1) : (i - st.top());
        st.push(i);
    }
