struct DNode {
    int data;
    DNode* prev;
    DNode* next;
};

DNode* swap_kth_ends(DNode* head, int k) {
    DNode* front = head;
    for (int i = 1; i < k; i++) front = front->next;
    DNode* back = head;
    while (back->next) back = back->next;
    for (int i = 1; i < k; i++) back = back->prev;
    if (front != back) {
        int tmp = front->data;
        front->data = back->data;
        back->data = tmp;
    }
    return head;
}

