int missing_number(const std::vector<int> &v) {
    int lo = 0, hi = (int)v.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == mid) lo = mid + 1;
        else hi = mid;
    }
    return v[lo] == lo ? lo + 1 : lo;
}

