    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    int pivot;
    cin >> pivot;
    three_way_partition(v, pivot);
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

