std::vector<int> two_sum_indices(std::vector<int> v, int k) {
    std::unordered_map<int, int> idx;
    for (int i = 0; i < (int)v.size(); i++) {
        int need = k - v[i];
        if (idx.count(need)) {
            std::vector<int> pair;
            pair.push_back(idx[need]);
            pair.push_back(i);
            return pair;
        }
        idx[v[i]] = i;
    }
    std::vector<int> none;
    none.push_back(-1);
    none.push_back(-1);
    return none;
}

