int find_root(std::vector<int>& parent, int x) {
    while (parent[x] != x) x = parent[x];
    return x;
}

void union_sets(std::vector<int>& parent, int a, int b) {
    int ra = find_root(parent, a);
    int rb = find_root(parent, b);
    if (ra != rb) parent[rb] = ra;
}

