    int q;
    std::cin >> q;
    std::vector<int> queries(q);
    for (int i = 0; i < q; i++) std::cin >> queries[i];
    std::vector<int> res = stock_lookup(ids, qtys, queries);
    for (size_t i = 0; i < res.size(); i++) {
