// Wordlist by Length Then Alphabet (insertion with two-part comparison)
#include <iostream>
#include <string>
#include <vector>
using namespace std;

vector<string> order_words(vector<string> words) {
    int n = (int)words.size();
    for (int i = 1; i < n; i++) {
        string key = words[i];
        int j = i - 1;
        while (j >= 0 && (words[j].size() > key.size() ||
                          (words[j].size() == key.size() && words[j] > key))) {
            words[j + 1] = words[j];
            j--;
        }
        words[j + 1] = key;
    }
    return words;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<string> words(n);
    for (int i = 0; i < n; i++) cin >> words[i];
    vector<string> res = order_words(words);
    for (int i = 0; i < n; i++)
        cout << res[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

// Workbook After k Insertion Steps (step i inserts index i)
#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<int> v(n);
    for (int i = 0; i < n; i++) cin >> v[i];
    long long k;
    cin >> k;
    for (int i = 1; i <= k && i < n; i++) {
        int key = v[i], j = i - 1;
        while (j >= 0 && v[j] > key) {
            v[j + 1] = v[j];
            j--;
        }
        v[j + 1] = key;
    }
    for (int i = 0; i < n; i++)
        cout << v[i] << (i + 1 < n ? ' ' : '\n');
    return 0;
}

#include <iostream>
#include <vector>

void dfs_label(int u, int id, const std::vector<std::vector<int>>& adj, std::vector<int>& label) {
    label[u] = id;
    for (size_t i = 0; i < adj[u].size(); i++) {
        int v = adj[u][i];
        if (label[v] == -1) dfs_label(v, id, adj, label);
    }
}

void component_labels(int V, const std::vector<std::vector<int>>& adj, std::vector<int>& out) {
    out.assign(V, -1);
    int id = 0;
    for (int i = 0; i < V; i++) {
        if (out[i] == -1) {
            dfs_label(i, id, adj, out);
            id++;
        }
    }
}

int main() {
    int V, E;
    std::cin >> V >> E;
    std::vector<std::vector<int>> adj(V);
    for (int i = 0; i < E; i++) {
        int u, v;
        std::cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    std::vector<int> out;
    component_labels(V, adj, out);
    for (int i = 0; i < V; i++) {
        if (i) std::cout << ' ';
        std::cout << out[i];
    }
    std::cout << "\n";
    return 0;
}

